  function openSettings(tab = profileView ? 'account' : 'appearance') { setAccountForm({ displayName: currentUser.displayName, username: currentUser.username, bio: currentUser.bio || '', badges: currentUser.badges || [], avatar: currentUser.avatar, banner: currentUser.banner || null, email: currentUser.email || '', password: '' }); setSettingsTab(tab); setSettingsOpen(true); }
  function openBadgeEditor(user) { if (!currentUser.isCreator) return; setBadgeMenu(null); setBadgeEditor({ user, badges: [...(user.badges || [])] }); }
  async function saveBadges(badges) { if (!badgeEditor) return; try { const result = await api.updateUserBadges(badgeEditor.user.id, badges); setBadgeEditor(null); setProfileView(null); setNotice('Insígnias atualizadas!'); if (badgeEditor.user.id === currentUser.id) onUserUpdate(result.user); } catch (err) { setNotice(err.message); } }
  function onAvatarFile(event) { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; if (file.size > 3 * 1024 * 1024) return setNotice('Escolha uma imagem de até 3 MB (GIF funciona!).'); const reader = new FileReader(); reader.onload = () => setAccountForm(current => current ? { ...current, avatar: String(reader.result) } : current); reader.readAsDataURL(file); }
  function onBannerFile(event) { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; if (file.size > 3 * 1024 * 1024) return setNotice('Escolha uma imagem de até 3 MB (GIF funciona!).'); const reader = new FileReader(); reader.onload = () => setAccountForm(current => current ? { ...current, banner: String(reader.result) } : current); reader.readAsDataURL(file); }
  function bannerStyle(banner) { if (!banner) return undefined; return String(banner).startsWith('data:image/') ? { backgroundImage: `url(${banner})`, backgroundSize: 'cover', backgroundPosition: 'center' } : { background: banner }; }
  async function saveProfile() { if (!accountForm) return setNotice('Nada para salvar.'); try { const input = { displayName: accountForm.displayName, username: accountForm.username, bio: accountForm.bio, avatar: accountForm.avatar, banner: accountForm.banner }; if (currentUser.isCreator) input.badges = accountForm.badges; const result = await api.updateMe(input); onUserUpdate(result.user); setNotice('Perfil atualizado!'); setSettingsOpen(false); } catch (err) { setNotice(err.message); } }
  async function saveProfileSettings(form) { try { const input = { displayName: form.displayName, username: form.username, bio: form.bio, avatar: form.avatar, banner: form.banner, email: form.email }; if (form.password) input.password = form.password; if (currentUser.isCreator) input.badges = form.badges; const result = await api.updateMe(input); onUserUpdate(result.user); setNotice('Perfil atualizado!'); setSettingsOpen(false); } catch (err) { setNotice(err.message); } }
  function openVoiceFromProfile(voice) { const found = servers.map(server => ({ server, channel: server.channels.find(item => item.id === voice.channelId) })).find(item => item.channel); if (!found) return setNotice('Entre no servidor dessa chamada para abrir.'); if (voiceConnected) leaveVoice(); setSelectedServer(found.server); setSelectedChannel(found.channel); setProfileView(null); joinVoice(found.channel); }
  async function sendMessage(event) { event.preventDefault(); if (!draft.trim() || !selectedChannel) return; try { const result = await api.sendMessage(selectedChannel.id, draft.trim()); setMessages(current => current.some(item => item.id === result.message.id) ? current : [...current, result.message]); setDraft(''); if (guideServer === selectedChannel.serverId) dismissGuide(); } catch (err) { setNotice(err.message); } }
  function createServer() { setServerModal({ step: 'choice', name: '', icon: null, template: null, server: null, busy: false }); }
  function onServerIconFile(event) { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; if (file.size > 1.5 * 1024 * 1024) return setNotice('Escolha uma imagem de até 1,5 MB.'); const reader = new FileReader(); reader.onload = () => setServerModal(current => current ? { ...current, icon: String(reader.result) } : current); reader.readAsDataURL(file); }
  async function submitCreateServer() { const modal = serverModal; if (!modal.name.trim() || modal.busy) return; setServerModal({ ...modal, busy: true }); try { const result = await api.createServer(modal.name.trim(), { icon: modal.icon, template: modal.template }); localStorage.setItem('sesh_onboarded', '1'); setServers(current => current.some(item => item.id === result.server.id) ? current : [...current, result.server]); setServerModal(null); setSelectedServer(result.server); setGuideServer(result.server.id); } catch (err) { setNotice(err.message); setServerModal({ ...modal, busy: false }); } }
  async function uploadServerIcon(event) { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; if (file.size > 1.5 * 1024 * 1024) return setNotice('Escolha uma imagem de até 1,5 MB.'); const reader = new FileReader(); reader.onload = async () => { try { const result = await api.updateServer(selectedServer.id, { icon: String(reader.result) }); setServers(current => current.map(item => item.id === result.server.id ? { ...item, icon: result.server.icon } : item)); setSelectedServer(current => current?.id === result.server.id ? { ...current, icon: result.server.icon } : current); setNotice('Ícone do servidor atualizado!'); } catch (err) { setNotice(err.message); } }; reader.readAsDataURL(file); }
  function dismissGuide() { if (guideServer) localStorage.setItem(`sesh_guide_${guideServer}`, '1'); setGuideServer(null); }
  async function submitJoinServer() { const modal = serverModal; const invite = modal.invite.trim(); if (!invite || modal.busy) return; setServerModal({ ...modal, busy: true }); try { const result = await api.joinServer(invite); localStorage.setItem('sesh_onboarded', '1'); setServers(current => current.some(item => item.id === result.server.id) ? current : [...current, result.server]); setSelectedServer(result.server); setServerModal(null); setNotice(`Você entrou em "${result.server.name}".`); } catch (err) { setNotice(err.message); setServerModal({ ...modal, busy: false }); } }
  function skipOnboard() { localStorage.setItem('sesh_onboarded', '1'); setOnboardOpen(false); }
  async function submitAddFriend(event) { event.preventDefault(); if (!addFriendValue.trim()) return; try { const result = await api.addFriend(addFriendValue.trim().replace(/^@/, '')); setNotice(result.accepted ? 'Vocês agora são amigos!' : `Convite enviado para @${addFriendValue.trim().replace(/^@/, '')}.`); setAddFriendValue(''); api.friends().then(setFriendsData).catch(() => {}); } catch (err) { setNotice(err.message); } }
  async function acceptFriendRequest(friendshipId) { try { await api.acceptFriend(friendshipId); api.friends().then(setFriendsData).catch(() => {}); } catch (err) { setNotice(err.message); } }
  async function removeFriendRow(friendshipId) { try { await api.removeFriend(friendshipId); api.friends().then(setFriendsData).catch(() => {}); } catch (err) { setNotice(err.message); } }
  async function createChannel(preType = 'text') { if (!selectedServer) return; if (!isOwner) return setNotice('Somente o dono do servidor pode criar canais.'); setChannelModal({ type: preType, name: '', private: false }); }
  async function submitChannelModal() { const modal = channelModal; const name = modal.name.trim(); if (!name) return; await addChannel(name, modal.type); setChannelModal(null); }
  async function addChannel(name, type) { if (!selectedServer || !name?.trim()) return; try { const result = await api.createChannel(selectedServer.id, { name: name.trim(), type }); applyServerChannels(selectedServer.id, channels => [...channels, result.channel]); setSelectedChannel(result.channel); } catch (err) { setNotice(err.message); } }
  async function editChannel(channel, name) { try { const result = await api.updateChannel(channel.id, { name }); applyServerChannels(channel.serverId, channels => channels.map(item => item.id === channel.id ? result.channel : item)); setSelectedChannel(current => current?.id === channel.id ? result.channel : current); setNotice('Canal atualizado.'); } catch (err) { setNotice(err.message); } }
  async function removeChannel(channel) { try { await api.deleteChannel(channel.id); applyServerChannels(channel.serverId, channels => channels.filter(item => item.id !== channel.id)); if (selectedChannel?.id === channel.id) { const remaining = selectedServer.channels.filter(item => item.id !== channel.id); setSelectedChannel(remaining.find(item => item.type === 'text') || remaining[0] || null); } setNotice('Canal excluído.'); } catch (err) { setNotice(err.message); } }
